const STATUS_META = {
  "Good": { color: "#2F9E5B", soft: "#E6F5EC", text: "#1E6E3E" },
  "Satisfactory": { color: "#D8B518", soft: "#FBF3D6", text: "#8A6E10" },
  "Moderate": { color: "#EA8C2E", soft: "#FCEADA", text: "#A85E14" },
  "Poor": { color: "#E1651F", soft: "#FBE2D3", text: "#9C440F" },
  "Very Poor": { color: "#D33B3B", soft: "#FADCDC", text: "#9E2323" },
  "Severe": { color: "#7C1F1F", soft: "#F2DADA", text: "#7C1F1F" },
};

function statusFromAQI(aqi) {
  if (aqi <= 50) return "Good";
  if (aqi <= 100) return "Satisfactory";
  if (aqi <= 200) return "Moderate";
  if (aqi <= 300) return "Poor";
  if (aqi <= 400) return "Very Poor";
  return "Severe";
}

/* ============================================================
   AWS API DATA LAYER
============================================================ */
const API_BASE = "http://65.2.121.61:8000";

async function fetchJSON(path, timeoutMs = 8000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);

  try {
    const response = await fetch(`${API_BASE}${path}`, {
      method: "GET",
      cache: "no-store",
      signal: controller.signal,
      headers: { Accept: "application/json" },
    });

    if (!response.ok) {
      throw new Error(`API ${response.status}: ${path}`);
    }

    return await response.json();
  } catch (error) {
    if (error?.name === "AbortError") {
      throw new Error(`API timeout after ${timeoutMs / 1000}s: ${path}`);
    }
    throw error;
  } finally {
    clearTimeout(timer);
  }
}

function toNumber(value, fallback = 0) {
  const n = Number(value);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeStation(s, index = 0) {
  const aqi = toNumber(s.aqi, null);
  const latitude = toNumber(s.latitude, null);
  const longitude = toNumber(s.longitude, null);

  // Convert real API latitude/longitude to coordinates for the existing SVG India map.
  const x = Number.isFinite(longitude)
    ? ((longitude - 68) / (97 - 68)) * MAP_W
    : null;
  const y = Number.isFinite(latitude)
    ? ((37 - latitude) / (37 - 6)) * MAP_H
    : null;

  return {
    ...s,
    id: s.id ?? s.station ?? `station-${index}`,
    station: s.station ?? s.id ?? `station-${index}`,
    city: s.city ?? "Unknown",
    state: s.state ?? "",
    area: s.area ?? s.location ?? s.station ?? s.city ?? "",
    latitude,
    longitude,
    lat: latitude,
    lon: longitude,
    x,
    y,
    aqi,
    pm25: s.pm25 == null ? null : toNumber(s.pm25, null),
    pm10: s.pm10 == null ? null : toNumber(s.pm10, null),
    no2: s.no2 == null ? null : toNumber(s.no2, null),
    so2: s.so2 == null ? null : toNumber(s.so2, null),
    co: s.co == null ? null : toNumber(s.co, null),
    o3: s.o3 == null ? null : toNumber(s.o3, null),
    nh3: s.nh3 == null ? null : toNumber(s.nh3, null),
    temp: s.temp == null ? null : toNumber(s.temp, null),
    humidity: s.humidity == null ? null : toNumber(s.humidity, null),
    status: s.status ?? (Number.isFinite(aqi) ? statusFromAQI(aqi) : "Moderate"),
    online: true,
    lastUpdated: new Date(s.timestamp ?? s.last_update ?? Date.now()),
  };
}

function normalizeHistoryItem(item) {
  const timestamp = item.timestamp ?? item.last_update ?? item.date ?? Date.now();
  return {
    ...item, station: item.station ?? item.id ?? "Unknown", city: item.city ?? "Unknown", timestamp,
    aqi: toNumber(item.aqi, null), pm25: toNumber(item.pm25, null), pm10: toNumber(item.pm10, null), no2: toNumber(item.no2, null),
    so2: toNumber(item.so2, null), co: toNumber(item.co, null), o3: toNumber(item.o3, null), nh3: toNumber(item.nh3, null)
  };
}

function normalizeAlert(a, index) {
  const level = String(a.level ?? a.severity ?? "info").toLowerCase();
  return {
    ...a, id: a.id ?? `${a.station ?? "alert"}-${a.timestamp ?? index}`,
    level: ["critical", "warning", "info"].includes(level) ? level : "info", station: a.station ?? "", city: a.city ?? "",
    message: a.message ?? a.description ?? `AQI alert: ${a.aqi ?? "N/A"}`, timestamp: a.timestamp ?? a.last_update ?? Date.now()
  };
}

function historyToTrend(history, stationId, pollutant, range) {
  const limits = {
    "1H": 1,
    "6H": 6,
    "24H": 24,
    "7D": 168,
    "30D": 720,
  };

  const cutoff =
    Date.now() - (limits[range] ?? 24) * 60 * 60 * 1000;

  return history
    .map((r) => {
      const rawTime = r.timestamp ?? r.last_update ?? r.date;

      return {
        ...r,
        _time: new Date(rawTime).getTime(),
        _station: String(r.station ?? r.id ?? ""),
        _value: Number(r[pollutant]),
      };
    })
    .filter((r) => {
      const stationMatch =
        !stationId ||
        r._station === String(stationId);

      const timeMatch =
        Number.isFinite(r._time) &&
        r._time >= cutoff;

      const valueMatch =
        Number.isFinite(r._value);

      return stationMatch && timeMatch && valueMatch;
    })
    .sort((a, b) => a._time - b._time)
    .map((r) => ({
      label: new Date(r._time).toLocaleTimeString("en-IN", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      value: r._value,
    }));
}

