/* Pseudo-random but stable helper */
function seededWave(i, base, amp, freq = 1) {
  return Math.round((base + Math.sin(i * freq) * amp + Math.cos(i * 0.6) * (amp / 2)) * 10) / 10;
}

function generateTrend(pollutantKey, range, seedBase) {
  const cfg = {
    "1H": { points: 12, stepMs: 5 * 60 * 1000, fmt: (d) => d.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }) },
    "6H": { points: 18, stepMs: 20 * 60 * 1000, fmt: (d) => d.toLocaleTimeString("en-IN", { hour: "2-digit", minute: "2-digit" }) },
    "24H": { points: 24, stepMs: 60 * 60 * 1000, fmt: (d) => d.toLocaleTimeString("en-IN", { hour: "2-digit" }) },
    "7D": { points: 7, stepMs: 24 * 60 * 60 * 1000, fmt: (d) => d.toLocaleDateString("en-IN", { weekday: "short" }) },
    "30D": { points: 30, stepMs: 24 * 60 * 60 * 1000, fmt: (d) => d.toLocaleDateString("en-IN", { day: "2-digit", month: "short" }) },
  }[range];
  const amp = seedBase * 0.22 + 4;
  const now = Date.now();
  const out = [];
  for (let i = 0; i < cfg.points; i++) {
    const t = new Date(now - (cfg.points - 1 - i) * cfg.stepMs);
    const val = Math.max(2, seededWave(i, seedBase, amp, pollutantKey === "aqi" ? 0.5 : 0.7));
    out.push({ label: cfg.fmt(t), value: val });
  }
  return out;
}

