const MAP_W = 460;
const MAP_H = 500;

function AQIMarker({ station, active, scale, onSelect }) {
  const m = STATUS_META[station.status];
  const r = (active ? 7.5 : 6) / scale;
  return (
    <g transform={`translate(${station.x}, ${station.y})`} className="cursor-pointer" onClick={() => onSelect(station)}>
      {active && <circle r={13 / scale} fill={m.color} opacity="0.2" />}
      <circle r={r} fill={m.color} stroke="#fff" strokeWidth={2 / scale} />
      {active && <circle r={2.6 / scale} fill="#fff" />}
      <text
        y={-9 / scale}
        textAnchor="middle"
        fontSize={10.5 / scale}
        fontWeight="600"
        fill="#16231D"
        stroke="#fff"
        strokeWidth={3 / scale}
        paintOrder="stroke"
      >
        {station.city}
      </text>
    </g>
  );
}

const IndiaMap = ({ stations, selected, onSelect }) => {
  const svgRef = useRef(null);
  const dragState = useRef(null);
  const [view, setView] = useState({ scale: 1, tx: 0, ty: 0 });

  const clampView = (v) => {
    const scale = Math.min(8, Math.max(1, v.scale));
    const maxPan = (scale - 1) * MAP_W * 0.6 + 40;
    return {
      scale,
      tx: Math.min(maxPan, Math.max(-maxPan, v.tx)),
      ty: Math.min(maxPan, Math.max(-maxPan, v.ty)),
    };
  };

  const zoomAt = (factor, pivotX = MAP_W / 2, pivotY = MAP_H / 2) => {
    setView((prev) => {
      const nextScale = Math.min(8, Math.max(1, prev.scale * factor));
      const k = nextScale / prev.scale;
      const tx = pivotX - k * (pivotX - prev.tx);
      const ty = pivotY - k * (pivotY - prev.ty);
      return clampView({ scale: nextScale, tx, ty });
    });
  };

  const toSvgPoint = (clientX, clientY) => {
    const svg = svgRef.current;
    const rect = svg.getBoundingClientRect();
    return {
      x: ((clientX - rect.left) / rect.width) * MAP_W,
      y: ((clientY - rect.top) / rect.height) * MAP_H,
    };
  };

  const handleWheel = (e) => {
    e.preventDefault();
    const p = toSvgPoint(e.clientX, e.clientY);
    zoomAt(e.deltaY < 0 ? 1.2 : 1 / 1.2, p.x, p.y);
  };

  const handlePointerDown = (e) => {
    dragState.current = { startX: e.clientX, startY: e.clientY, tx: view.tx, ty: view.ty };
    e.currentTarget.setPointerCapture(e.pointerId);
  };
  const handlePointerMove = (e) => {
    if (!dragState.current) return;
    const svg = svgRef.current;
    const rect = svg.getBoundingClientRect();
    const dx = ((e.clientX - dragState.current.startX) / rect.width) * MAP_W;
    const dy = ((e.clientY - dragState.current.startY) / rect.height) * MAP_H;
    setView((prev) => clampView({ ...prev, tx: dragState.current.tx + dx, ty: dragState.current.ty + dy }));
  };
  const handlePointerUp = () => { dragState.current = null; };

  const resetView = () => setView({ scale: 1, tx: 0, ty: 0 });

  return (
    <div className="relative">
      <div className="absolute right-2 top-2 z-10 flex flex-col gap-1 rounded-lg border border-[#E3E9E4] bg-white/95 p-1 shadow-sm">
        <button onClick={() => zoomAt(1.5)} className="rounded-md p-1.5 text-[#455950] hover:bg-[#F3F6F3]" aria-label="Zoom in">
          <ZoomIn size={15} />
        </button>
        <button onClick={() => zoomAt(0.67)} className="rounded-md p-1.5 text-[#455950] hover:bg-[#F3F6F3]" aria-label="Zoom out">
          <ZoomOut size={15} />
        </button>
        <button onClick={resetView} className="rounded-md p-1.5 text-[#455950] hover:bg-[#F3F6F3]" aria-label="Reset view">
          <Maximize2 size={13} />
        </button>
      </div>

      <svg
        ref={svgRef}
        viewBox={`0 0 ${MAP_W} ${MAP_H}`}
        onWheel={handleWheel}
        onPointerDown={handlePointerDown}
        onPointerMove={handlePointerMove}
        onPointerUp={handlePointerUp}
        onPointerLeave={handlePointerUp}
        className="mx-auto h-[380px] w-full max-w-md cursor-grab touch-none select-none active:cursor-grabbing sm:h-[440px]"
      >
        <g transform={`translate(${view.tx}, ${view.ty}) scale(${view.scale})`}>
          {INDIA_STATE_PATHS.map((f) => (
            <path
              key={f.name}
              d={f.d}
              fill="#DCEEE2"
              stroke="#9FC2AC"
              strokeWidth={0.8 / view.scale}
            />
          ))}
          {stations
            .filter((s) => Number.isFinite(Number(s.x)) && Number.isFinite(Number(s.y)))
            .map((s) => (
              <AQIMarker key={s.id} station={s} active={selected?.id === s.id} scale={view.scale} onSelect={onSelect} />
            ))}
        </g>
      </svg>

      <p className="pointer-events-none -mt-1 text-center text-[10px] text-[#8AA096]">Scroll or pinch to zoom &middot; drag to pan</p>

      <div className="flex flex-wrap items-center justify-center gap-x-4 gap-y-1.5 border-t border-[#EEF2EE] pt-3 text-[11px] text-[#5C6D64]">
        {Object.entries(STATUS_META).map(([label, m]) => (
          <span key={label} className="inline-flex items-center gap-1.5">
            <span className="h-2 w-2 rounded-full" style={{ background: m.color }} />
            {label}
          </span>
        ))}
      </div>
    </div>
  );
};

